-- 69 The Kraken: each tentacle is eleven bones with an ik_chain on the last;
-- this sweeps each chain's target about a mast (Skeleton.set_ik_target) and
-- FABRIK bends the whole limb to it. The storm - the ship's rocking, the
-- lightning - is the timeline on this entity; its event key calls on_thunder.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/69-the-kraken.scene"
local N, SEGS = 4, 11
local ROOTS = { { -330.0, -320.0 }, { -150.0, -335.0 }, { 170.0, -335.0 }, { 350.0, -320.0 } }
local captions, holding = true, true
local ends, ship = {}, nil
local t = 0

function init(entity)
    ship = Entity.find_by_name("Ship")
    for i = 0, N - 1 do ends[i] = Entity.find_by_name("T" .. i .. "Seg" .. (SEGS - 1)) end
end

function on_thunder(entity)
    Camera.shake(6, 0.4, 16)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then holding = not holding end
    t = t + dt
    local sx, sy = Transform.get_position(ship)
    local rot = Transform.get_rotation(ship)
    for i = 0, N - 1 do
        local e = ends[i]
        if e then
            local root = ROOTS[i + 1]
            local tx, ty
            if holding then
                -- A point on a mast that turns with the ship, swept in a loop.
                local mast = (i < 2) and -50 or 60
                local up = 40 + 60 * (0.5 + 0.5 * math.sin(t * 0.7 + i * 1.7))
                local lx, ly = mast + 55 * math.cos(t * 1.3 + i), up + 30 * math.sin(t * 1.1 + i * 2)
                tx = sx + lx * math.cos(rot) - ly * math.sin(rot)
                ty = sy + lx * math.sin(rot) + ly * math.cos(rot)
            else
                -- Let go: the tentacles wave above the water.
                tx = root[1] + 90 * math.sin(t * 0.9 + i * 1.3)
                ty = root[2] + 230 + 50 * math.sin(t * 1.4 + i)
            end
            Skeleton.set_ik_target(e, tx, ty)
        end
    end
end
